sql.where:
p.deleted=false
AND EXISTS (SELECT 1 FROM effective_problem_chapters pc WHERE pc.problem_id=p.id)
AND NOT EXISTS (SELECT 1 FROM effective_problem_chapters pc WHERE pc.problem_id=p.id AND pc.chapter_code NOT IN #{c})
AND FALSE
AND EXISTS (SELECT 1 FROM problem_curriculum pc JOIN problem_chapters ch USING(problem_id,curriculum_code) WHERE pc.problem_id=p.id AND pc.curriculum_code='PEP-A-2019' AND pc.confirmed AND ch.chapter_code IN #{c})
AND ( p.problem_number ILIKE CONCAT('%', #{keyword}, '%') OR EXISTS (SELECT 1 FROM problem_number_aliases a WHERE a.problem_id=p.id AND a.old_number ILIKE CONCAT('%', #{keyword}, '%')) OR COALESCE(p.title, '') ILIKE CONCAT('%', #{keyword}, '%') OR p.content ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(p.region, '') ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(ps.label, '') ILIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM problem_tags kpt JOIN tags kt ON kt.id=kpt.tag_id WHERE kpt.problem_id=p.id AND kt.name ILIKE CONCAT('%', #{keyword}, '%') ) )
AND p.year IN #{v}
AND p.source_code IN #{v}
AND p.question_type IN #{v}
AND p.difficulty IN #{v}
AND p.id IN ( SELECT fpt.problem_id FROM problem_tags fpt JOIN tags ft ON ft.id=fpt.tag_id WHERE ft.name IN #{v} GROUP BY fpt.problem_id )
